UPDATE t_quartz_task_status
SET status = #{taskStatusEntity.status},
    msg = #{taskStatusEntity.msg},
    update_time = #{taskStatusEntity.updateTime},
    end_time = #{taskStatusEntity.endTime}

    , begin_time = #{taskStatusEntity.beginTime}

WHERE plan_id = #{taskStatusEntity.planId}
  AND data_date = #{taskStatusEntity.dataDate}

mapper.select:
SELECT s.id AS id, s.plan_id AS planId, t.task_name AS taskName, t.task_cron AS taskCron, t.remark AS remark, t.task_type AS taskType, t.exe_path AS exePath, ( SELECT GROUP_CONCAT(d.pre_task_id ORDER BY d.pre_task_id SEPARATOR ',') FROM t_quartz_task_dependency d WHERE d.task_id = t.id AND d.dependency_type = 'DATA' ) AS dependId, ( SELECT GROUP_CONCAT(d.pre_task_id ORDER BY d.pre_task_id SEPARATOR ',') FROM t_quartz_task_dependency d WHERE d.task_id = t.id AND d.dependency_type = 'DATA' ) AS dataDependId, ( SELECT GROUP_CONCAT(d.pre_task_id ORDER BY d.pre_task_id SEPARATOR ',') FROM t_quartz_task_dependency d WHERE d.task_id = t.id AND d.dependency_type = 'CONTROL' ) AS controlDependId, t.datasource_id AS datasourceId, ds.name AS datasourceName, t.datasource_pool_id AS datasourcePoolId, dsp.name AS datasourcePoolName, t.task_system AS taskSystem, t.theme AS theme, t.period AS period, t.job_key AS jobKey, s.data_date AS dataDate, s.status AS status, s.begin_time AS beginTime, s.update_time AS updateTime, s.end_time AS endTime, s.msg AS msg, s.execute_pool_id AS executePoolId, s.execute_pool_name AS executePoolName, s.execute_datasource_id AS executeDatasourceId, s.execute_datasource_name AS executeDatasourceName, CASE WHEN s.status = '3' OR s.status = '4' THEN 'true' ELSE 'false' END AS _disabled, s.create_time AS createTime FROM t_quartz_task_status s INNER JOIN t_quartz_task t ON s.plan_id = t.id LEFT JOIN sys_datasource_config ds ON ds.id = t.datasource_id LEFT JOIN sys_datasource_pool dsp ON dsp.id = t.datasource_pool_id WHERE 1 = 1
AND s.update_time >= STR_TO_DATE(#{queryDTO.beginDate}, '%Y%m%d') AND s.update_time < DATE_ADD(STR_TO_DATE(#{queryDTO.beginDate}, '%Y%m%d'), INTERVAL 1 DAY)
AND s.data_date = #{queryDTO.dataDate}
AND t.id = #{queryDTO.id}
AND t.id IN
#{id}
AND s.id = #{queryDTO.statusId}
AND ( INSTR(CAST(s.id AS CHAR), #{queryDTO.taskName}) OR INSTR(CAST(s.plan_id AS CHAR), #{queryDTO.taskName}) OR INSTR(t.task_name, #{queryDTO.taskName}) OR INSTR(s.msg, #{queryDTO.taskName}) )
AND INSTR(t.task_system, #{queryDTO.taskSystem})
AND INSTR(t.theme, #{queryDTO.theme})
AND INSTR(t.remark, #{queryDTO.remark})
AND s.status = #{queryDTO.status}
ORDER BY s.update_time DESC

SELECT COUNT(1) AS totalInstances, COALESCE(SUM(CASE WHEN s.status = '1' THEN 1 ELSE 0 END), 0) AS waitingInstances, COALESCE(SUM(CASE WHEN s.status = '2' THEN 1 ELSE 0 END), 0) AS runningInstances, COALESCE(SUM(CASE WHEN s.status = '3' THEN 1 ELSE 0 END), 0) AS successInstances, COALESCE(SUM(CASE WHEN s.status = '4' THEN 1 ELSE 0 END), 0) AS failedInstances FROM t_quartz_task_status s INNER JOIN t_quartz_task t ON s.plan_id = t.id WHERE 1 = 1
AND s.update_time >= STR_TO_DATE(#{queryDTO.beginDate}, '%Y%m%d') AND s.update_time < DATE_ADD(STR_TO_DATE(#{queryDTO.beginDate}, '%Y%m%d'), INTERVAL 1 DAY)
AND s.data_date = #{queryDTO.dataDate}
AND t.id = #{queryDTO.id}
AND t.id IN
#{id}
AND s.id = #{queryDTO.statusId}
AND ( INSTR(CAST(s.id AS CHAR), #{queryDTO.taskName}) OR INSTR(CAST(s.plan_id AS CHAR), #{queryDTO.taskName}) OR INSTR(t.task_name, #{queryDTO.taskName}) OR INSTR(s.msg, #{queryDTO.taskName}) )
AND INSTR(t.task_system, #{queryDTO.taskSystem})
AND INSTR(t.theme, #{queryDTO.theme})
AND INSTR(t.remark, #{queryDTO.remark})

SELECT status
FROM t_quartz_task_status
WHERE plan_id = #{planId}
  AND data_date = #{dataDate}
ORDER BY COALESCE(update_time, create_time) DESC, id DESC
LIMIT 1

SELECT s.id, s.plan_id AS planId, s.data_date AS dataDate, s.status, s.begin_time AS beginTime, s.end_time AS endTime, s.msg, s.execute_pool_id AS executePoolId, s.execute_pool_name AS executePoolName, s.execute_datasource_id AS executeDatasourceId, s.execute_datasource_name AS executeDatasourceName, s.create_time AS createTime, s.update_time AS updateTime FROM t_quartz_task_status s WHERE s.plan_id IN
#{id}
AND s.data_date BETWEEN #{startDate} AND #{endDate} AND NOT EXISTS ( SELECT 1 FROM t_quartz_task_status newer_s WHERE newer_s.plan_id = s.plan_id AND newer_s.data_date = s.data_date AND ( COALESCE(newer_s.update_time, newer_s.create_time) > COALESCE(s.update_time, s.create_time) OR ( COALESCE(newer_s.update_time, newer_s.create_time) = COALESCE(s.update_time, s.create_time) AND newer_s.id > s.id ) ) )
